<?php
namespace Database\Seeders;
use App\Models\User; use App\Models\Venue; use App\Models\Event; use Illuminate\Database\Seeder; use Illuminate\Support\Facades\Hash;
class DatabaseSeeder extends Seeder { public function run():void { $password=Hash::make('password'); $admin=User::firstOrCreate(['email'=>'admin@tathkarti.test'],['name'=>'مدير النظام','password'=>$password,'role'=>'admin']); $org=User::firstOrCreate(['email'=>'organizer@tathkarti.test'],['name'=>'منظم تجريبي','phone'=>'+963900000001','password'=>$password,'role'=>'organizer']); $buyer=User::firstOrCreate(['email'=>'buyer@tathkarti.test'],['name'=>'مشتري تجريبي','phone'=>'+963900000002','password'=>$password,'role'=>'buyer']); $admin->tokens()->delete();$org->tokens()->delete();$buyer->tokens()->delete();$adminToken=$admin->createToken('demo-admin')->plainTextToken;$organizerToken=$org->createToken('demo-organizer')->plainTextToken;$buyerToken=$buyer->createToken('demo-buyer')->plainTextToken; $this->command->info('Admin token: '.$adminToken);$this->command->info('Organizer token: '.$organizerToken);$this->command->info('Buyer token: '.$buyerToken); $venue=Venue::firstOrCreate(['name'=>'مسرح دمشق'],['city'=>'دمشق','address'=>'وسط المدينة','capacity'=>5000]); for($i=1;$i<=8;$i++){ $e=Event::withoutGlobalScope('publicPublished')->firstOrCreate(['title'=>$i===1?'حفلة آلاف التذاكر':"فعالية تجريبية $i"],['organizer_id'=>$org->id,'venue_id'=>$venue->id,'description'=>'فعالية تجريبية لنظام تذكرتي','city'=>'دمشق','category'=>$i%2?'music':'theatre','starts_at'=>now()->addDays($i+5),'status'=>'published','max_per_order'=>8]);if(!$e->ticketTypes()->exists()){$e->ticketTypes()->create(['name'=>'عادي','type'=>'standard','price'=>25,'quantity'=>$i===1?5000:2000,'max_per_order'=>8]);$e->ticketTypes()->create(['name'=>'VIP','type'=>'vip','price'=>75,'quantity'=>500,'max_per_order'=>4]);}} $now=now();$rows=[];for($i=1;$i<=1200;$i++)$rows[]=['name'=>"حامل تذكرة $i",'email'=>"holder$i@tathkarti.test",'password'=>$password,'role'=>'buyer','created_at'=>$now,'updated_at'=>$now];foreach(array_chunk($rows,500) as $batch)User::upsert($batch,['email'],['name']); } }
